async (): Promise<ImageGenerationRequestAssembly | null> => {
    const currentPromptDraft = promptDraftRef.current;
    flushPromptDraft(currentPromptDraft);
    const latestCanvasState = useCanvasStore.getState();
    const latestNode = latestCanvasState.nodes.find((candidate) => candidate.id === id);
    const latestData = latestNode && isImageEditNode(latestNode) ? latestNode.data : data;
    const latestSettings = useSettingsStore.getState();
    const latestReferences = collectInputReferences(id, latestCanvasState.nodes, latestCanvasState.edges);
    const referenceContextPrompt = buildReferenceContextPrompt(latestReferences);
    const latestIncomingImages = latestReferences
      .filter((reference) => reference.kind === 'image' && reference.imageUrl)
      .map((reference) => reference.imageUrl as string);
    let basePrompt = normalizeReferenceTokensForSubmission(currentPromptDraft, latestReferences);

    const selectedPresetId = latestData.selectedPromptPresetId ?? null;
    const selectedFunctionChip = selectedPresetId ? null : latestData.selectedFunctionChip ?? null;
    if (selectedPresetId && latestData.selectedFunctionChip) {
      updateNodeData(id, { selectedFunctionChip: null });
    }

    let sourcePrompt = '';
    if (selectedPresetId) {
      const selectedPreset = latestSettings.promptPresets.find((preset) => preset.id === selectedPresetId);
      if (!selectedPreset) {
        const errorMessage = t('node.imageEdit.promptPresetMissing');
        setError(errorMessage);
        void showErrorDialog(errorMessage, t('common.error'));
        return null;
      }
      sourcePrompt = selectedPreset.prompt.trim();
    } else if (selectedFunctionChip) {
      sourcePrompt = buildMultiFunctionPromptFromSettings(
        selectedFunctionChip as MultiFunctionType,
        latestSettings
      ).trim();
    }

    if (sourcePrompt && basePrompt) {
      const normalizedBasePrompt = normalizePromptForSourceComparison(basePrompt);
      const knownSourcePrompts = [
        sourcePrompt,
        ...latestSettings.promptPresets.map((preset) => preset.prompt),
        ...MULTI_FUNCTION_ITEMS.map((item) =>
          buildMultiFunctionPromptFromSettings(item.id, latestSettings)
        ),
      ];
      const basePromptIsStaleSourcePrompt = knownSourcePrompts.some((promptSource) =>
        normalizePromptForSourceComparison(promptSource) === normalizedBasePrompt
      );
      if (basePromptIsStaleSourcePrompt) {
        basePrompt = '';
      }
    }

    if (!basePrompt && !sourcePrompt) {
      const errorMessage = t('node.imageEdit.promptRequired');
      setError(errorMessage);
      void showErrorDialog(errorMessage, t('common.error'));
      return null;
    }
    if (!basePrompt && sourcePrompt && latestIncomingImages.length === 0) {
      const errorMessage = t('node.imageEdit.referenceRequiredForPromptSource');
      setError(errorMessage);
      void showErrorDialog(errorMessage, t('common.error'));
      return null;
    }

    // Append the cinematography prompt at submit time (not into the user's
    // textbox — see handleCameraControlApply).
    let prompt = sourcePrompt && basePrompt
      ? `${sourcePrompt}\n\n${t('node.imageEdit.userSupplementLabel')}${basePrompt}`
      : sourcePrompt || basePrompt;

    const cc = latestData.cameraControl;
    if (cc?.enabled === true) {
      try {
        const cameraPrompt = buildCameraPrompt({
          cameraId: cc.camera,
          lensId: cc.lens,
          focalLengthMm: cc.focalLength,
          apertureF: cc.aperture,
        }, latestSettings);
        if (cameraPrompt) prompt = `${prompt}, ${cameraPrompt}`;
      } catch { /* fall back to current prompt */ }
    }

    // Resolve the panel-configured model (custom provider / Dreamina CLI) that
    // the user picked via <ModelConfigPicker /> on this exact node. Built-in
    // models no longer surface in the picker, so we go through the gateway's
    // dispatch instead of the old `selectedModel.resolveRequest(...)` path.
    const latestNodeModelConfig = latestData.modelConfig ?? nodeModelConfig ?? null;
    const resolved = resolveActiveModelForPanel('aiImageNode', latestNodeModelConfig);
    if ((resolved.entryId.startsWith('custom:') || resolved.entryId.startsWith('agnes:')) && resolved.requiresApiKey && !resolved.apiKey) {
      const msg = `服务商「${resolved.providerLabel}」未填写 API Key`;
      setError(msg);
      void showErrorDialog(msg, t('common.error'));
      return null;
    }
    if (!resolved.entryId.startsWith('dreamina:') && !resolved.entryId.startsWith('custom:') && !resolved.entryId.startsWith('agnes:')) {
      // Fallback: no custom provider configured and no Dreamina login. Prompt
      // the user to set one up in 我的配置.
      const msg = '请先在「设置 → 我的配置」里添加至少一个服务商，或在「Dreamina」里登录 CLI 后再生成。';
      setError(msg);
      void showErrorDialog(msg, t('common.error'));
      return null;
    }

    const effectiveCount = customCount ? Math.min(10, Math.max(1, parseInt(customCount, 10) || 1)) : generateCount;
    const batchId = effectiveCount > 1 ? `batch-${Date.now()}` : undefined;
    const generationDurationMs = 60000;
    const generationStartedAt = Date.now();
    const firstGeneratedSequence = resolveNextGeneratedMediaSequence(
      'image',
      latestCanvasState.nodes
    );
    const generatedDateStamp = getLocalDateStamp();
    setError(null);
    setShowCountPicker(false);

    let referenceAspectRatio: string | undefined;
    if (resolved.ratio === 'auto') {
      if (latestIncomingImages.length > 0) {
        try {
          referenceAspectRatio = await detectAspectRatio(latestIncomingImages[0]);
        } catch {
          referenceAspectRatio = undefined;
        }
      }
    }

    const effectiveExtraParamsRecord = effectiveExtraParams as Record<string, unknown>;
    const requestResolutionLabel =
      resolved.extraParams?.['resolutionType'] ??
      resolved.extraParams?.['size'] ??
      effectiveExtraParamsRecord['resolutionType'] ??
      effectiveExtraParamsRecord['size'] ??
      selectedResolution.value ??
      '2K';
    const geometry = normalizeImageRequestGeometry({
      selectedResolution: requestResolutionLabel,
      selectedAspectRatio: resolved.ratio,
      referenceAspectRatio,
      supportedAspectRatios: resolved.supportedRatios,
      fallbackResolution: '2K',
    });
    const requestSize = geometry.requestSize;
    const resolvedRequestAspectRatio = geometry.requestAspectRatio;
    const promptWithReferenceContext = referenceContextPrompt
      ? `${referenceContextPrompt}\n\n${prompt}`
      : prompt;
    const promptForRequest = appendGenerationParameterConstraints(promptWithReferenceContext, {
      enabled: latestSettings.appendParameterConstraintsToPrompt,
      aspectRatio: geometry.promptAspectRatio,
      resolution: geometry.resolutionLabel,
      count: effectiveCount,
    });

    const extraParams = {
      ...effectiveExtraParams,
      ...resolved.extraParams,
      resolutionType: geometry.resolutionLabel,
    };
    return {
      promptForRequest,
      requestSize,
      resolvedRequestAspectRatio,
      latestIncomingImages,
      effectiveCount,
      batchId,
      firstGeneratedSequence,
      generatedDateStamp,
      generationStartedAt,
      generationDurationMs,
      resolved,
      gatewayPayload: {
        prompt: promptForRequest,
        model: resolved.modelForGateway,
        size: requestSize,
        aspectRatio: resolvedRequestAspectRatio,
        referenceImages: latestIncomingImages,
        extraParams,
      },
    };
  }

AiVideoNode.tsx.callback:
(): VideoGenerationRequestAssembly | null => {
    const latestPromptDraft = promptDraftRef.current;
    flushPromptDraft(latestPromptDraft);
    const latestCanvasState = useCanvasStore.getState();
    const latestNode = latestCanvasState.nodes.find((candidate) => candidate.id === id);
    const latestData = latestNode && isAiVideoNode(latestNode) ? latestNode.data : data;
    const latestSettings = useSettingsStore.getState();
    const latestCatalog = buildVideoModelCatalog(
      useCustomProvidersStore.getState().providers,
      latestSettings.agnesApiKey,
      latestSettings.dreaminaStatus
    );
    const latestModelConfig = resolveVideoModelConfig(latestCatalog, latestData.modelConfig ?? resolvedModelConfig);
    const latestEntry = resolveConfigEntry(latestCatalog, latestModelConfig);
    const latestReferences = collectInputReferences(id, latestCanvasState.nodes, latestCanvasState.edges);
    const basePrompt = normalizeReferenceTokensForSubmission(latestPromptDraft, latestReferences);
    let sourcePrompt = '';
    if (latestData.selectedPromptPresetId) {
      const selectedPreset = latestSettings.promptPresets.find((preset) => preset.id === latestData.selectedPromptPresetId);
      if (!selectedPreset) {
        const message = t('node.imageEdit.promptPresetMissing');
        setError(message);
        void showErrorDialog(message, t('common.error'));
        return null;
      }
      sourcePrompt = selectedPreset.prompt.trim();
    }
    let composedPrompt = sourcePrompt && basePrompt
      ? `${sourcePrompt}\n\n${t('node.imageEdit.userSupplementLabel')}${basePrompt}`
      : sourcePrompt || basePrompt;
    const cc = latestData.cameraControl;
    if (cc?.enabled === true) {
      try {
        const cameraPrompt = buildCameraPrompt({
          cameraId: cc.camera,
          lensId: cc.lens,
          focalLengthMm: cc.focalLength,
          apertureF: cc.aperture,
        }, latestSettings);
        if (cameraPrompt) {
          composedPrompt = composedPrompt ? `${composedPrompt}, ${cameraPrompt}` : cameraPrompt;
        }
      } catch {
        // Keep the user's prompt if camera prompt assembly fails.
      }
    }
    const referenceContextPrompt = buildReferenceContextPrompt(latestReferences);
    const prompt = referenceContextPrompt
      ? `${referenceContextPrompt}\n\n${composedPrompt}`
      : composedPrompt;
    if (!prompt) {
      const message = t('node.aiVideo.promptRequired');
      setError(message);
      void showErrorDialog(message, t('common.error'));
      return null;
    }
    if (!latestModelConfig || !latestEntry) {
      const message = t('node.aiVideo.noVideoProvider');
      setError(message);
      void showErrorDialog(message, t('common.error'));
      return null;
    }
    if (!latestEntry.usable) {
      const message = latestEntry.notReadyReason ?? t('node.aiVideo.noVideoProvider');
      setError(message);
      void showErrorDialog(message, t('common.error'));
      return null;
    }
    const latestInputSchema = resolveEntryInputSchema(latestEntry);
    const latestIncomingImages = latestInputSchema.images.enabled
      ? latestReferences
        .filter((reference) => reference.kind === 'image' && reference.imageUrl)
        .map((reference) => reference.imageUrl as string)
      : [];
    const latestIncomingVideos = latestInputSchema.video.enabled
      ? latestReferences
        .filter((reference) => reference.kind === 'video' && reference.videoUrl)
        .map((reference) => reference.videoUrl as string)
      : [];
    const latestIncomingAudios = latestInputSchema.audio.enabled
      ? latestReferences
        .filter((reference) => reference.kind === 'audio' && reference.audioUrl)
        .map((reference) => reference.audioUrl as string)
      : [];
    const overflow = getVideoReferenceOverflow(latestInputSchema, {
      images: latestIncomingImages.length,
      video: latestIncomingVideos.length,
      audio: latestIncomingAudios.length,
    });
    if (overflow) {
      const message = t(`videoInputModes.limitErrors.${overflow.kind}`, { count: overflow.count, max: overflow.max });
      setError(message);
      void showErrorDialog(message, t('common.error'));
      return null;
    }
    if (latestIncomingImages.length < latestInputSchema.images.min) {
      const message = `当前模型至少需要 ${latestInputSchema.images.min} 张图片引用。`;
      setError(message);
      void showErrorDialog(message, t('common.error'));
      return null;
    }
    if (latestIncomingVideos.length < latestInputSchema.video.min) {
      const message = `当前模型至少需要 ${latestInputSchema.video.min} 个视频引用。`;
      setError(message);
      void showErrorDialog(message, t('common.error'));
      return null;
    }
    if (latestIncomingAudios.length < latestInputSchema.audio.min) {
      const message = `当前模型至少需要 ${latestInputSchema.audio.min} 个音频引用。`;
      setError(message);
      void showErrorDialog(message, t('common.error'));
      return null;
    }
    const outputAspectRatio =
      aspectRatioFromPixelResolution(latestModelConfig.resolution)
      ?? latestModelConfig.aspectRatio
      ?? '16:9';
    const extraParams = { ...(latestModelConfig.extraParams ?? {}) };
    extraParams.videoInputSchema = latestInputSchema;
    if (latestEntry.id === 'dreamina:multi-frame-video' && latestIncomingImages.length >= 3) {
      const transitions = parseDreaminaTransitionSegments(
        extraParams.dreaminaTransitionSegments ?? extraParams.transitionSegments,
      );
      const expectedCount = latestIncomingImages.length - 1;
      const transitionIssues = validateDreaminaVideoRequest({
        command: 'multiframe2video',
        resolution: latestModelConfig.resolution,
        duration: Number(latestModelConfig.duration) || undefined,
        ratio: latestModelConfig.aspectRatio,
        imageCount: latestIncomingImages.length,
        videoCount: 0,
        audioCount: 0,
        transitions,
      }).filter(({ field }) => field === 'transitions' || field.startsWith('transitions.'));
      if (transitions?.length !== expectedCount || transitionIssues.length > 0) {
        const message = t('node.aiVideo.multiframeIncomplete', { count: expectedCount });
        setParamsOpen(true);
        setError(message);
        void showErrorDialog(message, t('common.error'));
        return null;
      }
    }

    return {
      prompt,
      latestModelConfig,
      latestEntry,
      latestIncomingImages,
      latestIncomingVideos,
      latestIncomingAudios,
      outputAspectRatio,
      gatewayPayload: {
        prompt,
        model: latestModelConfig.entryId,
        size: latestModelConfig.resolution,
        aspectRatio: latestModelConfig.aspectRatio,
        seconds: Number(latestModelConfig.duration) || undefined,
        referenceImages: latestIncomingImages,
        referenceVideos: latestIncomingVideos,
        referenceAudios: latestIncomingAudios,
        extraParams,
      },
    };
  }
